function check([nums, indexDifference, valueDifference], actual, expected) {
  if (!Array.isArray(actual) || actual.length !== 2) return false;
  const [i, j] = actual;
  if (expected[0] === -1) return i === -1 && j === -1;
  if (!Number.isInteger(i) || !Number.isInteger(j)) return false;
  if (i < 0 || j < 0 || i >= nums.length || j >= nums.length) return false;
  return Math.abs(i - j) >= indexDifference && Math.abs(nums[i] - nums[j]) >= valueDifference;
}

