  if (!nums.every(v => Number.isInteger(v) && v >= 0 && v <= 50)) return 'Each value is an integer from 0 to 50.';
  if (!Number.isInteger(indexDifference) || indexDifference < 0 || indexDifference > 100) return 'indexDifference is between 0 and 100.';
  if (!Number.isInteger(valueDifference) || valueDifference < 0 || valueDifference > 50) return 'valueDifference is between 0 and 50.';
  return null;
}

