function findIndices(nums, indexDifference, valueDifference) {
  // Collect every ordered pair that qualifies, then report the last one found.
  const pairs = [];
  for (let i = 0; i < nums.length; i++)
    for (let j = 0; j < nums.length; j++)
      if (Math.abs(i - j) >= indexDifference && Math.abs(nums[i] - nums[j]) >= valueDifference) pairs.push([i, j]);
  return pairs.length ? pairs[pairs.length - 1] : [-1, -1];
}

