function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const top = size === 'large' ? 50 : Math.floor(rand() * 12);
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (top + 1)));
  const indexDifference = Math.floor(rand() * (Math.min(n + 1, 100) + 1));
  const valueDifference = Math.floor(rand() * (Math.min(top + 2, 50) + 1));
  return [nums, indexDifference, valueDifference];
}
